1: /**
2:  * Shared formatting utilities for tool call display.
3:  *
4:  * Used by both:
5:  * - ui/components/ToolCall.tsx (Ink REPL)
6:  * - cli/output/renderer.ts (headless text output)
7:  */
8: 
9: import { sep } from "node:path";
10: 
11: /** Maximum preview lines for tool output. */
12: export const MAX_PREVIEW_LINES = 4;
13: export const MAX_LINE_WIDTH = 88;
14: 
15: /**
16:  * Argument keys that carry filesystem paths. Values for these keys are
17:  * relativized against process.cwd() before display so users see
18:  * "src/ui/App.tsx" instead of "/Users/.../codeshell/src/ui/App.tsx".
19:  */
20: const PATH_ARG_KEYS = new Set(["file_path", "path", "directory", "cwd"]);
21: 
22: /**
23:  * Strip the cwd prefix from a path string for display. Paths outside
24:  * cwd, relative paths, and non-string values are returned unchanged.
25:  */
26: function relativizePath(value: string): string {
27:   if (!value || !value.startsWith("/")) return value;
28:   const cwd = process.cwd();
29:   const prefix = cwd.endsWith(sep) ? cwd : cwd + sep;
30:   if (value === cwd) return ".";
31:   if (value.startsWith(prefix)) return value.slice(prefix.length);
32:   return value;
33: }
34: 
35: /** Tool name → display color for the dot indicator. */
36: export const TOOL_DOT_COLORS: Record<string, string> = {
37:   Read: "ansi:blue",
38:   Write: "ansi:green",
39:   Edit: "ansi:yellow",
40:   Bash: "ansi:magenta",
41:   Glob: "ansi:blue",
42:   Grep: "ansi:blue",
43:   Agent: "ansi:cyan",
44:   WebSearch: "ansi:blue",
45:   WebFetch: "ansi:blue",
46:   LSP: "ansi:cyan",
47:   TodoWrite: "ansi:cyan",
48: };
49: 
50: /** Mapping of tool names to their most informative argument keys. */
51: const TOOL_ARG_KEYS: Record<string, string[]> = {
52:   Read: ["file_path"],
53:   Write: ["file_path"],
54:   Edit: ["file_path"],
55:   Glob: ["pattern"],
56:   Grep: ["pattern", "path"],
57:   Bash: ["command"],
58:   WebSearch: ["query"],
59:   WebFetch: ["url"],
60:   Agent: ["description"],
61:   TodoWrite: ["todos"],
62:   Sleep: ["seconds"],
63:   EnterWorktree: ["target", "slug"],
64:   CronCreate: ["name", "schedule"],
65:   LSP: ["action", "file_path"],
66:   NotebookEdit: ["action", "file_path"],
67:   Config: ["action", "key"],
68: };
69: 
70: /**
71:  * Strip a leading `cd <dir> && ` (or `; `) so the visible command is the
72:  * thing the user actually cares about. The cwd prefix is mechanical noise
73:  * that otherwise eats the entire truncation budget on long absolute paths.
74:  */
75: function stripCdPrefix(cmd: string): string {
76:   // Matches: cd <path> && rest   |   cd "<path with spaces>" && rest   |   cd '...'; rest
77:   const m = cmd.match(/^\s*cd\s+(?:"[^"]*"|'[^']*'|\S+)\s*(?:&&|;)\s*(.+)$/s);
78:   return m ? m[1]!.trim() : cmd;
79: }
80: 
81: /**
82:  * Format tool arguments into a compact one-line summary.
83:  */
84: export function formatToolArgs(toolName: string, args: Record<string, unknown>): string {
85:   const keys = TOOL_ARG_KEYS[toolName] ?? Object.keys(args).slice(0, 2);
86:   const parts: string[] = [];
87:   for (const k of keys) {
88:     const v = args[k];
89:     if (v !== undefined && !k.startsWith("__")) {
90:       let s = String(v);
91:       if (toolName === "Bash" && k === "command") s = stripCdPrefix(s);
92:       else if (PATH_ARG_KEYS.has(k)) s = relativizePath(s);
93:       // Bash commands deserve more room than other args — the truncation
94:       // budget here used to swallow `git diff …` after a long cd prefix.
95:       const max = toolName === "Bash" && k === "command" ? MAX_LINE_WIDTH : 60;
96:       parts.push(truncate(s, max));
97:     }
98:   }
99:   // Read often pages large files via offset/limit — show a range suffix so
100:   // back-to-back reads of the same file are visually distinguishable.
101:   if (toolName === "Read") {
102:     const offset = typeof args.offset === "number" ? args.offset : undefined;
103:     const limit = typeof args.limit === "number" ? args.limit : undefined;
104:     if (offset !== undefined || limit !== undefined) {
105:       const start = offset ?? 1;
106:       const end = limit !== undefined ? start + limit - 1 : undefined;
107:       parts.push(end !== undefined ? `:${start}-${end}` : `:${start}-`);
108:     }
109:   }
110:   return parts.length > 0 ? parts.join(" ") : truncate(JSON.stringify(args), 80);
111: }
112: 
113: /** Truncate a string to max length with ellipsis. */
114: export function truncate(s: string, max: number): string {
115:   return s.length > max ? s.slice(0, max - 1) + "…" : s;
116: }
117: 
118: /** Collapse multiline text to a single line. */
119: export function singleLine(s: string): string {
120:   return s.replace(/\n/g, " ").replace(/\s+/g, " ").trim();
121: }
122: 
123: /** Format byte count in human-readable form. */
124: export function formatBytes(n: number): string {
125:   if (n >= 1024 * 1024) return (n / (1024 * 1024)).toFixed(1) + "MB";
126:   if (n >= 1024) return (n / 1024).toFixed(1) + "KB";
127:   return n + "B";
128: }
129: 
130: // ─── Compact Output ────────────────────────────────────────────────
131: 
132: export interface CompactResult {
133:   summary: string;
134:   preview: string[];
135:   moreLines: number;
136: }
137: 
138: /**
139:  * Produce a compact summary of tool output for display.
140:  */
141: export function compactOutput(toolName: string, content: string): CompactResult {
142:   const lines = content.split("\n");
143:   const totalLines = lines.length;
144: 
145:   switch (toolName) {
146:     case "Read":
147:       return {
148:         summary: `${totalLines} lines, ${formatBytes(content.length)}`,
149:         preview: [],
150:         moreLines: 0,
151:       };
152: 
153:     case "Bash": {
154:       if (totalLines <= MAX_PREVIEW_LINES) {
155:         return {
156:           summary: "",
157:           preview: lines.map((l) => truncate(l, MAX_LINE_WIDTH)),
158:           moreLines: 0,
159:         };
160:       }
161:       return {
162:         summary: `${totalLines} lines output`,
163:         preview: lines.slice(0, MAX_PREVIEW_LINES).map((l) => truncate(l, MAX_LINE_WIDTH)),
164:         moreLines: totalLines - MAX_PREVIEW_LINES,
165:       };
166:     }
167: 
168:     case "Glob": {
169:       const fileCount = lines.filter((l) => l.trim()).length;
170:       return {
171:         summary: `${fileCount} files found`,
172:         preview: lines.slice(0, 5).map((l) => truncate(l, MAX_LINE_WIDTH)),
173:         moreLines: Math.max(0, fileCount - 5),
174:       };
175:     }
176: 
177:     case "Grep": {
178:       const matchCount = lines.filter((l) => l.trim()).length;
179:       return {
180:         summary: `${matchCount} matches`,
181:         preview: lines.slice(0, MAX_PREVIEW_LINES).map((l) => truncate(l, MAX_LINE_WIDTH)),
182:         moreLines: Math.max(0, matchCount - MAX_PREVIEW_LINES),
183:       };
184:     }
185: 
186:     case "Write":
187:       return { summary: singleLine(content).slice(0, 60), preview: [], moreLines: 0 };
188: 
189:     case "Edit":
190:       return { summary: singleLine(content).slice(0, 70), preview: [], moreLines: 0 };
191: 
192:     case "Agent":
193:       return { summary: truncate(singleLine(content), 80), preview: [], moreLines: 0 };
194: 
195:     case "TodoWrite":
196:       return { summary: singleLine(content), preview: [], moreLines: 0 };
197: 
198:     default: {
199:       if (totalLines <= 1) {
200:         return { summary: truncate(content, 80), preview: [], moreLines: 0 };
201:       }
202:       return {
203:         summary: `${totalLines} lines`,
204:         preview: lines.slice(0, MAX_PREVIEW_LINES).map((l) => truncate(l, MAX_LINE_WIDTH)),
205:         moreLines: Math.max(0, totalLines - MAX_PREVIEW_LINES),
206:       };
207:     }
208:   }
209: }
